-- =========================================================================
-- V10: Multi-Release Headers & Disabled Packets Audit
-- 1) Registra enums do Old Navigator em todas as releases (mortos fora de 2013/R63A).
-- 2) Header de retry do Doorbell para PRODUCTION-201611291003-338511768 (685).
-- 3) Marca override_method = 'DISABLED' em pacotes com ausência comprovada por era.
-- 4) Reverte override_method em pacotes vivos onde marcas anteriores foram errôneas.
-- =========================================================================

-- 1) Enums do Old Navigator em todas as releases
INSERT INTO `releases_incoming_headers` (`release_name`, `name`, `header`, `override_method`)
SELECT r.`release_name`, n.`name`, NULL, 'DISABLED'
FROM `releases` r
CROSS JOIN (
    SELECT 'NAVIGATOR_CAN_CREATE_ROOM' AS `name`
    UNION ALL SELECT 'NAVIGATOR_FRIENDS_IN_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_FRIENDS_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_HIGHEST_SCORE_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_LATEST_EVENTS'
    UNION ALL SELECT 'NAVIGATOR_LIST_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_MY_FAVORITES'
    UNION ALL SELECT 'NAVIGATOR_MY_HISTORY'
    UNION ALL SELECT 'NAVIGATOR_MY_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_OFFICIAL_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_POPULAR_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_POPULAR_TAGS'
    UNION ALL SELECT 'NAVIGATOR_PROMO_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_TAG_SEARCH'
) n
WHERE r.`release_name` <> 'RELEASE63-201305221112-286302280'
  AND NOT EXISTS (
    SELECT 1 FROM `releases_incoming_headers` h
    WHERE h.`release_name` = r.`release_name` AND h.`name` = n.`name`
);

INSERT INTO `releases_outgoing_headers` (`release_name`, `name`, `header`, `override_method`)
SELECT r.`release_name`, n.`name`, NULL, 'DISABLED'
FROM `releases` r
CROSS JOIN (
    SELECT 'NAVIGATOR_CAN_CREATE_ROOM' AS `name`
    UNION ALL SELECT 'NAVIGATOR_LIST_ROOMS'
    UNION ALL SELECT 'NAVIGATOR_POPULAR_TAGS'
) n
WHERE r.`release_name` <> 'RELEASE63-201305221112-286302280'
  AND NOT EXISTS (
    SELECT 1 FROM `releases_outgoing_headers` h
    WHERE h.`release_name` = r.`release_name` AND h.`name` = n.`name`
);

-- 2) Doorbell retry composer no Flash 2016
UPDATE `releases_incoming_headers`
SET `header` = 685, `override_method` = NULL
WHERE `release_name` = 'PRODUCTION-201611291003-338511768' AND `name` = 'ROOM_LOAD_BY_DOORBELL';

